import UIKit

// The platforms' logos, from cr3dentials-frontend public/images, rendered to 144 px PNGs (3x of 48 pt), and the
// Cr3dentials mark. A platform not listed here shows its initial instead.
enum PlatformLogos {
    /// The logo for a platform's name as our backend gives it ("Deel", "PayPal"), or nil.
    static func image(for name: String) -> UIImage? {
        let key = name.lowercased().filter { $0.isLetter || $0.isNumber }
        return pngs[key].flatMap { Data(base64Encoded: $0) }.flatMap { UIImage(data: $0, scale: 3) }
    }

    /// The Cr3dentials mark, for the footer.
    static let mark: UIImage? = Data(base64Encoded: markPng).flatMap { UIImage(data: $0, scale: 3) }

    private static let pngs: [String: String] = [
        "airbnb": "",
        "bolt": "",
        "deel": "",
        "onlyfans": "",
        "paypal": "",
        "shopify": "",
        "uber": "",
        "upwork": "",
        "x": "",
        "youtube": "",
    ]

    private static let markPng = ""
}
